import java.util.Comparator;
import java.util.List;
import java.util.Objects;

public final class AvlMap<K, V> {
    private static final class Node<K, V> {
        K key;
        V value;
        Node<K, V> left;
        Node<K, V> right;
        int height = 1;

        Node(K key, V value) {
