    private final Comparator<? super K> comparator;
    private Node<K, V> root;
    private int size;

    public AvlMap(Comparator<? super K> comparator) {
        this.comparator = Objects.requireNonNull(comparator);
    }

    public int size() {
        return size;
    }

    public V get(K key) {
        Objects.requireNonNull(key);
        Node<K, V> cur = root;
        while (cur != null) {
            int c = comparator.compare(key, cur.key);
            if (c == 0) return cur.value;
            cur = c < 0 ? cur.left : cur.right;
        }
        return null;
    }

    public void put(K key, V value) {
        Objects.requireNonNull(key);
        root = put(root, key, value);
    }

    private Node<K, V> put(Node<K, V> node, K key, V value) {
        if (node == null) {
            size++;
            return new Node<>(key, value);
        }

        int c = comparator.compare(key, node.key);
        if (c < 0) {
            node.left = put(node.left, key, value);
        } else if (c > 0) {
            node.right = put(node.right, key, value);
        } else {
            node.value = value;
            return node;
        }

        updateHeight(node);
        return rebalance(node);
    }

    private Node<K, V> rebalance(Node<K, V> node) {
        int bf = balanceFactor(node);

        if (bf > 1) {
            if (balanceFactor(node.left) < 0) {
                node.left = rotateLeft(node.left);
            }
            return rotateRight(node);
        }

        if (bf < -1) {
            if (balanceFactor(node.right) > 0) {
                node.right = rotateRight(node.right);
            }
            return rotateLeft(node);
        }

        return node;
    }

    private Node<K, V> rotateLeft(Node<K, V> x) {
        Node<K, V> y = x.right;
        Node<K, V> b = y.left;

        y.left = x;
        x.right = b;

        updateHeight(x);
        updateHeight(y);

        return y;
    }

    private Node<K, V> rotateRight(Node<K, V> y) {
        Node<K, V> x = y.left;
        Node<K, V> b = x.right;

        x.right = y;
        y.left = b;

        updateHeight(y);
        updateHeight(x);

        return x;
    }

    private static int height(Node<?, ?> node) {
        return node == null ? 0 : node.height;
    }

    private static int balanceFactor(Node<?, ?> node) {
        return height(node.left) - height(node.right);
    }

    private static void updateHeight(Node<?, ?> node) {
        node.height = 1 + Math.max(height(node.left), height(node.right));
    }

    public List<K> keysInOrder() {
        ArrayList<K> out = new ArrayList<>();
        inOrder(root, out);
        return out;
    }

    private void inOrder(Node<K, V> node, List<K> out) {
        if (node == null) return;
        inOrder(node.left, out);
        out.add(node.key);
        inOrder(node.right, out);
    }

    public void assertInvariants() {
        assertInvariants(root, null, null);
    }

    private int assertInvariants(Node<K, V> node, K lowExclusive, K highExclusive) {
        if (node == null) return 0;

        if (lowExclusive != null && comparator.compare(node.key, lowExclusive) <= 0) {
